$grouping = list_random(['(',')'],['[',']']); ($answer,$bplusc) = (3..9)[NchooseK(7,2)]; $a = $answer*$bplusc; $b = random(1,$bplusc-1,1); $c = $bplusc - $b; Context("LimitedNumeric"); $answer = Real($a/($b+$c));
############################# # Exercise Group Introduction #############################
BEGIN_PGML Use the order of operations to simplify the expression that has grouping symbols.
END_PGML
###### # Body ######
BEGIN_PGML [`[$a] \div [$grouping->[0]] [$b] + [$c] [$grouping->[1]]`]
[_]{$answer}{5}
END_PGML
